using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;
class Inspect {static IEnumerable<TypeDefinition> All(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in All(t.NestedTypes))yield return n;}}static void Main(string[] a){using(var x=AssemblyDefinition.ReadAssembly(a[0]))foreach(var t in All(x.MainModule.Types)){if(a.Length>2 && t.FullName.IndexOf(a[1],StringComparison.OrdinalIgnoreCase)>=0){Console.WriteLine("TYPE "+t.FullName+" : "+t.BaseType);foreach(var f in t.Fields)Console.WriteLine("FIELD "+f);foreach(var m in t.Methods){Console.WriteLine("METHOD "+m);if(a[2]=="il" && m.HasBody)foreach(var i in m.Body.Instructions)Console.WriteLine(i);}}else if(a.Length==2 && t.FullName.IndexOf(a[1],StringComparison.OrdinalIgnoreCase)>=0)Console.WriteLine(t.FullName);}}}
